[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$InnerBase64 = ""
$ExpectedInnerSha256 = "90ae28fafc9e19daf0d40c7685371226f0588ae857d6b8a23859c5e4bc096c4e"
$InnerPath = Join-Path -Path $env:TEMP -ChildPath "Orion-P4-02B1-v4-inner.ps1"

Write-Host "P4-02B1 v4 parser gate"
Write-Host "The profile-configured s6 gateway enablement is hash-checked and Windows-PowerShell-parsed before runtime changes."
Write-Host ""

[System.IO.File]::WriteAllBytes(
    $InnerPath,
    [Convert]::FromBase64String($InnerBase64)
)

$actualSha = (Get-FileHash -LiteralPath $InnerPath -Algorithm SHA256).Hash.ToLowerInvariant()
if ($actualSha -ne $ExpectedInnerSha256) {
    throw "P4-02B1 v4 inner script SHA256 verification failed."
}

Write-Host "P4_02B1_V4_INNER_HASH=PASS"

$parseErrors = $null
$tokens = $null
[System.Management.Automation.Language.Parser]::ParseFile(
    $InnerPath,
    [ref]$tokens,
    [ref]$parseErrors
) | Out-Null

if ($parseErrors.Count -ne 0) {
    $messages = ($parseErrors | ForEach-Object { $_.ToString() }) -join [Environment]::NewLine
    throw ("P4-02B1 v4 inner parser check failed:{0}{1}" -f [Environment]::NewLine, $messages)
}

Write-Host "P4_02B1_V4_INNER_PARSE=PASS"

$args = @(
    "-NoProfile",
    "-ExecutionPolicy", "Bypass",
    "-File", $InnerPath
)

$savedPreference = $ErrorActionPreference
$ErrorActionPreference = "Continue"

try {
    $output = & powershell.exe @args 2>&1
    $code = $LASTEXITCODE
}
finally {
    $ErrorActionPreference = $savedPreference
}

$output | ForEach-Object { Write-Host ([string]$_) }

if ($code -ne 0) {
    throw ("P4-02B1 v4 inner enablement failed with exit {0}." -f $code)
}

Write-Host "P4_02B1_V4_OUTER=PASS"
